import Extend from 'flarum/common/extenders';
import Group from 'flarum/common/models/Group';
import Badge from 'flarum/common/components/Badge';
import app from 'flarum/admin/app';
export default [new Extend.Admin().setting(() => function () {
  const selected = this.setting('fof-top-posters-widget.excludeGroups', '[]');
  let selectedGroupIds = JSON.parse(selected());
  return m("div", {
    className: "Form-group EditUserModal-groups"
  }, m("label", null, app.translator.trans('fof-top-posters-widget.admin.settings.info')), app.store.all('groups').filter(g => g.id() !== Group.GUEST_ID).map(g => m("div", null, m("label", {
    className: "checkbox"
  }, m("input", {
    type: "checkbox",
    checked: selectedGroupIds.includes(g.id()),
    onchange: event => {
      const checkbox = event.target;
      if (checkbox.checked) {
        selectedGroupIds.push(g.id());
      } else {
        selectedGroupIds = selectedGroupIds.filter(id => id !== g.id());
      }
      selected(JSON.stringify(selectedGroupIds));
    }
  }), m(Badge, {
    icon: g.icon() || 'fas fa-user',
    color: g.color()
  }), " ", g.namePlural()))));
})];